type CreateRepoInputBodyObjectFormat string

const (
	CreateRepoInputBodyObjectFormatSHA1   CreateRepoInputBodyObjectFormat = "sha1"
	CreateRepoInputBodyObjectFormatSHA256 CreateRepoInputBodyObjectFormat = "sha256"
)

// AllValues returns all CreateRepoInputBodyObjectFormat values.
func (CreateRepoInputBodyObjectFormat) AllValues() []CreateRepoInputBodyObjectFormat {
	return []CreateRepoInputBodyObjectFormat{
		CreateRepoInputBodyObjectFormatSHA1,
		CreateRepoInputBodyObjectFormatSHA256,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s CreateRepoInputBodyObjectFormat) MarshalText() ([]byte, error) {
	switch s {
	case CreateRepoInputBodyObjectFormatSHA1:
		return []byte(s), nil
	case CreateRepoInputBodyObjectFormatSHA256:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *CreateRepoInputBodyObjectFormat) UnmarshalText(data []byte) error {
	switch CreateRepoInputBodyObjectFormat(data) {
	case CreateRepoInputBodyObjectFormatSHA1:
		*s = CreateRepoInputBodyObjectFormatSHA1
